# find trajectories for case thefuck-32 (passing dev)
for target_case in ['thefuck-32','thefuck-8']:
    print('#'*30, target_case)
    tids=[]
    for r in recs:
        if r['case_id']==target_case and r['trajectory_id'] not in tids: tids.append(r['trajectory_id'])
    tid=tids[0]
    print('traj',tid)
    for e in recs:
        if e['trajectory_id']!=tid: continue
        d={k:v for k,v in e.items() if k not in ('workspace','result','output')}
        print(json.dumps(d)[:1000])
        if 'result' in e: print('  result:', repr(e['result'])[:400])
        if 'output' in e: print('  output:', repr(e['output'])[-600:])
    print()
