/usr/bin/python3 - <<'PY'
import json, collections
reqs=[json.loads(l) for l in open('/workspace/observed_run/request_traces.jsonl')]
evs=[json.loads(l) for l in open('/workspace/observed_run/tool_traces.jsonl')]
by=collections.defaultdict(list)
for e in evs: by[e['trajectory_id']].append(e)
rew={t:( [e for e in v if e['event']=='grade'][-1]['reward'] if any(e['event']=='grade' for e in v) else None) for t,v in by.items()}
case={t:v[0]['case_id'] for t,v in by.items()}
# trajectory -> (mode,step)
meta={}
for r in reqs:
    for t in r['trajectory_ids']:
        meta[t]=(r['mode'],r['step'])
agg=collections.defaultdict(lambda:[0,0])
for t,(m,s) in meta.items():
    if t not in rew: continue
    agg[(m,s,case[t])][0]+=1
    agg[(m,s,case[t])][1]+=rew[t]
for k in sorted(agg): print(k, agg[k])
print('--- totals by (mode,step) ---')
tot=collections.defaultdict(lambda:[0,0])
for (m,s,c),(n,r) in agg.items():
    tot[(m,s)][0]+=n; tot[(m,s)][1]+=r
for k in sorted(tot): print(k,tot[k], 'mean', round(tot[k][1]/tot[k][0],4))
PY

